response:
[
  {
    "id": 1,
    "source": "Am Dienstag hat sich in Sachsen-Anhalt der neue Landtag konstituiert.",
    "text": "روز سه‌شنبه، مجلس ایالتی جدید در زاکسن-آنهالت تشکیل شد"
  },
  {
    "id": 2,
    "source": "In den vergangenen Jahrzehnten keine große Sache, doch diesmal war alles anders.",
    "text": "در دهه‌های گذشته این موضوع مسئله مهمی نبود، اما این بار همه چیز متفاوت بود"
  },
  {
    "id": 3,
    "source": "Die in Sachsen-Anhalt als gesichert rechtsextremistisch geltende AfD erhielt den Posten des Landtagspräsidenten.",
    "text": "حزب AfD که در زاکسن-آنهالت به عنوان یک گروه راست‌گرای افراطی شناخته‌شده تلقی می‌شود، کرسی ریاست مجلس ایالتی را به دست آورد"
  },
  {
    "id": 4,
    "source": "Zahlreiche Medien beobachteten die Wahl, auch aus dem Ausland.",
    "text": "رسانه‌های متعددی، از جمله رسانه‌های خارجی، این انتخابات را زیر نظر داشتند"
  },
  {
    "id": 5,
    "source": "Darüber spreche ich jetzt mit Jens Thurau, unserem Korrespondenten aus dem Hauptstadtstudio.",
    "text": "در این باره اکنون با ینس توراو، خبرنگار ما از دفتر پایتخت صحبت می‌کنم"
  },
  {
    "id": 6,
    "source": "Jens, du warst auch in Magdeburg.",
    "text": "ینس، تو هم در ماگدبورگ بودی"
  },
  {
    "id": 7,
    "source": "Wie war denn der Tag gestern?",
    "text": "روز گذشته چطور گذشت؟"
  },
  {
    "id": 8,
    "source": "Ja, fangen wir vielleicht mal so an.",
    "text": "بله، شاید بهتر باشد این‌طور شروع کنیم"
  },
  {
    "id": 9,
    "source": "Also erstmal starke Polizeipräsenz rund um den Landtag.",
    "text": "اول از همه، حضور گسترده پلیس در اطراف ساختمان مجلس ایالتی"
  },
  {
    "id": 10,
    "source": "Der ist vis-à-vis des berühmten Magdeburger Doms.",
    "text": "این ساختمان درست روبروی کلیسای جامع معروف ماگدبورگ قرار دارد"
  },
  {
    "id": 11,
    "source": "Da war eigentlich alles mehr oder weniger abgesperrt, schon Stunden vorher.",
    "text": "در واقع آنجا کم‌وبیش از ساعت‌ها قبل کاملاً مسدود شده بود"
  },
  {
    "id": 12,
    "source": "Man wusste also, es könnte brisant werden auf diesem Platz.",
    "text": "بنابراین مشخص بود که اوضاع در این میدان می‌تواند حساس شود"
  },
  {
    "id": 13,
    "source": "Zwischen Dom und Landtag haben sich dann ungefähr bei der Eröffnung der Landtagssitzung so um 11 Uhr,",
    "text": "بین کلیسای جامع و مجلس ایالتی، تقریباً هنگام افتتاح جلسه مجلس در حدود ساعت ۱۱ صبح،"
  },
  {
    "id": 14,
    "source": "ja ich würde mal schätzen so 1000 Leute versammelt, um gegen die",
    "text": "بله، تخمین می‌زنم حدود ۱۰۰۰ نفر جمع شده بودند تا علیه"
  },
  {
    "id": 15,
    "source": "in Sachsen-Anhalt gesichert rechtsextreme Alternative für Deutschland zu protestieren.",
    "text": "حزب «جایگزینی برای آلمان» که در زاکسن-آنهالت به عنوان راست‌گرای افراطی شناخته می‌شود، اعتراض کنند"
  },
  {
    "id": 16,
    "source": "Und da gab es dann schon einige merkwürdige Begegnungen.",
    "text": "و در آنجا برخوردهای عجیبی هم رخ داد"
  },
  {
    "id": 17,
    "source": "Ulrich Siegmund, der AfD-Spitzenkandidat, hat sich zu den Demonstranten gesellt und versucht mit ihnen zu sprechen.",
    "text": "اولریش زیگموند، نامزد اصلی AfD، به معترضان پیوست و سعی کرد با آن‌ها صحبت کند"
  },
  {
    "id": 18,
    "source": "Das ist nicht richtig gelungen, aber auch andere Abgeordnete von anderen Parteien aus dem Landtag waren dabei.",
    "text": "این کار به درستی پیش نرفت، اما نمایندگان دیگری از احزاب دیگر مجلس ایالتی هم آنجا حضور داشتند"
  },
  {
    "id": 19,
    "source": "Das war dann schon das erste äußere Kennzeichen dafür, dass hier was Außergewöhnliches geschieht.",
    "text": "این اولین نشانه بیرونی بود که نشان می‌داد اتفاقی غیرعادی در حال وقوع است"
  },
  {
    "id": 20,
    "source": "Ja, aber die Sitzung im Landtag selber war dann bemerkenswert und spektakulär, sieht man mal von dem Wahlergebnis.",
    "text": "بله، اما خود جلسه در مجلس ایالتی، صرف‌نظر از نتیجه انتخابات، قابل توجه و تماشایی بود"
  },
  {
    "id": 21,
    "source": "über das wir ja sicher noch sprechen werden.",
    "text": "که مطمئناً هنوز درباره آن صحبت خواهیم کرد"
  },
  {
    "id": 22,
    "source": "Genau, das Ergebnis der Wahl war doch etwas überraschend,",
    "text": "دقیقاً، نتیجه انتخابات تا حدی غافلگیرکننده بود"
  },
  {
    "id": 23,
    "source": "denn Tobias Rausch hat noch mehr Stimmen als erwartet bekommen.",
    "text": "چرا که توبیاس راوش آرای بیشتری نسبت به آنچه انتظار می‌رفت به دست آورد"
  },
  {
    "id": 24,
    "source": "Und das hat auch auf Bundesebene in der Koalition für Aufregung gesorgt.",
    "text": "و این موضوع در سطح فدرال نیز در ائتلاف حاکم باعث ایجاد جنجال شد"
  },
  {
    "id": 25,
    "source": "Ich stelle fest, dass scheinbar in der CDU-Fraktion ja die Maßgabe galt, dass man sich enthält.",
    "text": "من متوجه شدم که ظاهراً در فراکسیون CDU این دستورالعمل وجود داشته که باید رأی ممتنع داد"
  }
]

[
  {
    "id": 1,
    "source": "gegangen in Berlin.",
    "text": "در برلین اتفاق افتاده است"
  },
  {
    "id": 2,
    "source": "Der Bebelplatz ist ja bekannt dafür, dass 1933 nach der Machtübernahme die Nationalsozialisten dort ihre",
    "text": "میدان ببل‌پلاتس به این معروف است که نازی‌ها در سال ۱۹۳۳ پس از به قدرت رسیدن،"
  },
  {
    "id": 3,
    "source": "schlimme Bücherverbrennung veranstaltet haben.",
    "text": "کتاب‌سوزان وحشتناک خود را در آنجا برگزار کردند"
  },
  {
    "id": 4,
    "source": "Die SPD-Abgeordneten hatten das Grundgesetz in der Hand und haben gesagt, wir sind jetzt bereit,",
    "text": "نمایندگان حزب سوسیال دموکرات قانون اساسی را در دست داشتند و گفتند که ما اکنون آماده‌ایم"
  },
  {
    "id": 5,
    "source": "Demokratie und Rechtsstaat zu verteidigen.",
    "text": "از دموکراسی و دولت قانون‌مدار دفاع کنیم"
  },
  {
    "id": 6,
    "source": "Also da kommt sicher auch für die Regierungskoalition hier in Berlin noch einiger Gesprächsbedarf dazu.",
    "text": "بنابراین قطعاً نیاز به گفتگوهای بیشتری برای ائتلاف حاکم در اینجا در برلین وجود خواهد داشت"
  },
  {
    "id": 7,
    "source": "Die CDU muss erklären, wie sie es weiterhält mit ihrer Distanz zu den Rechtsextremen.",
    "text": "حزب دموکرات مسیحی باید توضیح دهد که چگونه می‌خواهد فاصله خود را با راست‌گرایان افراطی حفظ کند"
  },
  {
    "id": 8,
    "source": "Schauen wir wieder zurück nach Magdeburg, auf die Personen, die dort nun führend und im Amt sind.",
    "text": "بیایید دوباره به ماگدبورگ نگاه کنیم، به افرادی که اکنون در آنجا در مقام‌های رهبری و مسئولیت هستند"
  },
  {
    "id": 9,
    "source": "Wer ist denn dieser Landtagspräsident Tobias Rausch?",
    "text": "این توبیاس راوش، رئیس مجلس ایالتی، کیست؟"
  },
  {
    "id": 10,
    "source": "Das ist ein 35-jähriger Industriekaufmann, der eigentlich nach außen hin, wie er selber sagt,",
    "text": "او یک کارشناس بازرگانی ۳۵ ساله است که در ظاهر، همان‌طور که خودش می‌گوید،"
  },
  {
    "id": 11,
    "source": "kein Hardliner sei, auch nicht so wirkt.",
    "text": "یک تندرو نیست و چنین به نظر هم نمی‌رسد"
  },
  {
    "id": 12,
    "source": "Gestern zum Beispiel nach seiner Wahl dann eine halbwegs verbindliche Rede auch an die anderen Fraktionen im",
    "text": "برای مثال، دیروز پس از انتخابش، سخنرانی نسبتاً محترمانه‌ای خطاب به سایر فراکسیون‌ها در"
  },
  {
    "id": 13,
    "source": "Landtag gehalten hat, aber man weiß, dass er über ein",
    "text": "مجلس ایالتی ایراد کرد، اما می‌دانیم که او"
  },
  {
    "id": 14,
    "source": "gutes Netzwerk auch mit den Extremrechten in seiner Partei verfügt.",
    "text": "شبکه ارتباطی خوبی با راست‌گرایان افراطی در حزب خود دارد"
  },
  {
    "id": 15,
    "source": "Und bekannt geworden ist er unter anderem über die Landesgrenzen von Sachsen-Anhalt zu Jahresbeginn.",
    "text": "و او از جمله در ابتدای سال فراتر از مرزهای ایالت زاکسن-آنهالت شناخته شد"
  },
  {
    "id": 16,
    "source": "Da ist ja vielen AfD-Politikern in Land und im Bund vorgeworfen worden, Vetternwirtschaft zu betreiben,",
    "text": "در آن زمان، بسیاری از سیاستمداران حزب «آلترناتیو برای آلمان» در سطح ایالتی و فدرال متهم به پارتی‌بازی شدند"
  },
  {
    "id": 17,
    "source": "in ihren Abgeordnetenbüros zum Beispiel.",
    "text": "برای مثال در دفاتر نمایندگی‌شان"
  },
  {
    "id": 18,
    "source": "Und Rausch hat durchaus zugegeben, Er ist in seinem Heimatort ein engagierter",
    "text": "و راوش کاملاً پذیرفته است که او در زادگاهش یک"
  },
  {
    "id": 19,
    "source": "Fußballspieler und dort auch im Fußballverein aktiv.",
    "text": "فوتبالیست متعهد است و در باشگاه فوتبال آنجا فعالیت دارد"
  },
  {
    "id": 20,
    "source": "Und mehrere Spieler aus diesem Fußballverein arbeiten jetzt in seinem Abgeordnetenbüro.",
    "text": "و چندین بازیکن از همین باشگاه فوتبال اکنون در دفتر نمایندگی او کار می‌کنند"
  },
  {
    "id": 21,
    "source": "Also das hat zumindest ein Geschmäckle.",
    "text": "بنابراین این موضوع حداقل کمی شائبه‌برانگیز است"
  },
  {
    "id": 22,
    "source": "Man wird abwarten müssen, wie das mit Tobias Rausch weitergeht.",
    "text": "باید منتظر ماند و دید که وضعیت توبیاس راوش چگونه پیش می‌رود"
  },
  {
    "id": 23,
    "source": "Gestern hat er sich einigermaßen konziliant gezeigt.",
    "text": "او دیروز تا حدی رویکردی آشتی‌جویانه نشان داد"
  },
  {
    "id": 24,
    "source": "Schauen wir einmal auf die Funktion des Landtagspräsidenten.",
    "text": "بیایید نگاهی به وظیفه رئیس مجلس ایالتی بیندازیم"
  },
  {
    "id": 25,
    "source": "Kannst du uns erklären, welche Aufgaben er hat und warum die anderen Fraktionen in der Personalie Rausch jetzt so eine",
    "text": "می‌توانی برای ما توضیح دهی که او چه وظایفی دارد و چرا سایر فراکسیون‌ها در مورد انتخاب راوش اکنون چنین"
  }
]

[
  {
    "id": 1,
    "source": "Problematik sehen?",
    "text": "مشکل را می‌بینید؟"
  },
  {
    "id": 2,
    "source": "Er ist formal der höchste Politiker in Sachsen-Anhalt, noch vor dem Ministerpräsidenten.",
    "text": "او از نظر رسمی بالاترین مقام سیاسی در زاکسن-آنهالت است، حتی بالاتر از نخست‌وزیر ایالتی"
  },
  {
    "id": 3,
    "source": "Er leitet die Sitzung des Landtages.",
    "text": "او ریاست جلسات پارلمان ایالتی را بر عهده دارد"
  },
  {
    "id": 4,
    "source": "Er kann diverse Posten auch in der Landtagsverwaltung vergeben.",
    "text": "او همچنین می‌تواند سمت‌های مختلفی را در مدیریت پارلمان ایالتی تعیین کند"
  },
  {
    "id": 5,
    "source": "Das hat die AfD ja auch schon angekündigt.",
    "text": "حزب آلترناتیو برای آلمان (AfD) هم این موضوع را از قبل اعلام کرده بود"
  },
  {
    "id": 6,
    "source": "Er repräsentiert das Land nach außen.",
    "text": "او نماینده ایالت در مجامع بیرونی است"
  },
  {
    "id": 7,
    "source": "Das heißt also zum Beispiel auch... Bei bestimmten Gedenktagen dann Reden im Landtag oder woanders zu halten.",
    "text": "این یعنی برای مثال... در روزهای یادبود خاص، در پارلمان ایالتی یا جاهای دیگر سخنرانی کند"
  },
  {
    "id": 8,
    "source": "Das ist schon eine herausragende Position, diese Präsident, so wie ja der Bundestagspräsident in diesem Fall,",
    "text": "این جایگاه بسیار برجسته‌ای است، این رئیس، درست مانند رئیس بوندستاگ در این مورد"
  },
  {
    "id": 9,
    "source": "die Bundestagspräsidentin Julia Glöckner auch eine herausragende Position hat.",
    "text": "که رئیس بوندستاگ، یولیا گلوکنر، نیز جایگاه برجسته‌ای دارد"
  },
  {
    "id": 10,
    "source": "Das ist nicht irgendwer und damit erklärt sich auch die gesamte Aufregung um die Wahl von Tobias Rausch.",
    "text": "او فرد معمولی نیست و به همین دلیل تمام هیاهو پیرامون انتخاب توبیاس راوش قابل درک است"
  },
  {
    "id": 11,
    "source": "Auch der erste Stellvertreter des Landtagspräsidenten kommt von der AfD.",
    "text": "اولین معاون رئیس پارلمان ایالتی نیز از حزب AfD است"
  },
  {
    "id": 12,
    "source": "Was weiß man denn über Hans-Thomas Tillschneider?",
    "text": "چه چیزی درباره هانس-توماس تیلیشنایدر می‌دانیم؟"
  },
  {
    "id": 13,
    "source": "Ja, das ist jetzt wirklich ein ausgewiesener Vertreter des innerhalb der AfD nochmal extremen Flügels.",
    "text": "بله، او واقعاً نماینده شناخته‌شده‌ای از جناح افراطی‌تر در داخل حزب AfD است"
  },
  {
    "id": 14,
    "source": "Wir nennen das ja den völkischen Flügel.",
    "text": "ما به آن جناح «فولکیش» (ملی‌گرای قومی) می‌گوییم"
  },
  {
    "id": 15,
    "source": "Bekannt ist ja der Fraktionsvorsitzende.",
    "text": "رئیس فراکسیون شناخته‌شده است"
  },
  {
    "id": 16,
    "source": "Im thüringischen Landtag Höcke, der diesen Flügel vertritt, der ja sogar,",
    "text": "در پارلمان ایالتی تورینگن، هوکه که نماینده این جناح است، که حتی"
  },
  {
    "id": 17,
    "source": "wenn man jetzt mal ins Ausland guckt und die rechtsextremen und rechtsradikalen Parteien dort vergleicht,",
    "text": "اگر به خارج از کشور نگاه کنید و احزاب راست افراطی و رادیکال آنجا را مقایسه کنید"
  },
  {
    "id": 18,
    "source": "denen ist diese Position der AfD eindeutig zu viel.",
    "text": "برای آن‌ها این موضع حزب AfD به وضوح بیش از حد است"
  },
  {
    "id": 19,
    "source": "Die haben sich abgewandt von der AfD, weil dieser klar völkische Kurs ja eigentlich nichts anderes ist als das Primat",
    "text": "آن‌ها از AfD روی برگردانده‌اند، زیرا این مسیر آشکارا ملی‌گرایانه قومی، در واقع چیزی جز اولویت"
  },
  {
    "id": 20,
    "source": "der Abstammung.",
    "text": "اصل و نسب نیست"
  },
  {
    "id": 21,
    "source": "Also das, was man sozusagen das Blut nennt, das hier herrscht, also die deutsche Abstammung,",
    "text": "یعنی همان چیزی که به اصطلاح «خون» نامیده می‌شود که در اینجا حاکم است، یعنی تبار آلمانی"
  },
  {
    "id": 22,
    "source": "die jetzt über allen anderen stehen soll, das propagiert Tillschneider und macht da auch überhaupt keinen Hehl draus.",
    "text": "که اکنون باید بالاتر از همه قرار بگیرد؛ تیلیشنایدر این را تبلیغ می‌کند و اصلاً هم آن را پنهان نمی‌کند"
  },
  {
    "id": 23,
    "source": "Also innerhalb der AfD nochmal ein wirklich extremer... Vertreter,",
    "text": "بنابراین در داخل AfD، او واقعاً یک نماینده بسیار افراطی است"
  },
  {
    "id": 24,
    "source": "der dann jetzt auch noch Vizepräsident im Landtag ist.",
    "text": "که حالا نایب‌رئیس پارلمان ایالتی هم شده است"
  },
  {
    "id": 25,
    "source": "Als weitere Personalie wurde gestern dann auch der CDU-Abgeordnete Carsten Borchert als zweiter Vizepräsident gewählt,",
    "text": "به عنوان یک انتصاب دیگر، دیروز کارستن بورشرت، نماینده حزب CDU، به عنوان دومین نایب‌رئیس انتخاب شد"
  }
]

[
  {
    "id": 1,
    "source": "Die CDU-Fraktion scheint sich an alle möglichen Absprachen zu halten, aber ganz bestimmt nicht mehr an solche,",
    "text": "به نظر می‌رسد فراکسیون CDU به تمام توافق‌های ممکن پایبند است، اما قطعاً دیگر به توافق‌هایی که"
  },
  {
    "id": 2,
    "source": "die Sven Schulze zu verantworten hat.",
    "text": "اسون شولتسه مسئول آن‌هاست، پایبند نیست"
  },
  {
    "id": 3,
    "source": "Die nächste große Wahl, die dann stattfinden soll, ist im Dezember die des Ministerpräsidenten.",
    "text": "انتخابات بزرگ بعدی که قرار است برگزار شود، انتخاب نخست‌وزیر در ماه دسامبر است"
  },
  {
